[CmdletBinding()]
param(
  [Parameter(Mandatory)][string]$ZipPath,
  [Parameter(Mandatory)][string]$MetadataPath,
  [Parameter(Mandatory)][string]$ControlsReceiptPath,
  [Parameter(Mandatory)][string]$StageRoot,
  [Parameter(Mandatory)][string]$FactoryRoot,
  [Parameter(Mandatory)][string]$ControlRoot,
  [Parameter(Mandatory)][string]$ControlReceiptRoot,
  [Parameter(Mandatory)][string]$PlanPath,
  [Parameter(Mandatory)][string]$ManifestPath,
  [Parameter(Mandatory)][string]$RunManifestPath,
  [Parameter(Mandatory)][string]$RunRoot,
  [Parameter(Mandatory)][string]$Base,
  [Parameter(Mandatory)][string]$LockPath,
  [Parameter(Mandatory)][string]$WorkloadExe,
  [Parameter(Mandatory)][string]$RendererDll,
  [Parameter(Mandatory)][string]$PresentMonExe,
  [switch]$RunControls
)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$MaxJson=[int64]2097152;$MaxSource=[int64]67108864;$MaxTotal=[int64]134217728;$MaxZip=[int64]134217728;$Chunk=65536;$Memory=[int64]1073741824
$Expected=@{workloadExe=@{bytes=[int64]5233152;sha='7e749248800da8e6058b0b69ccbab2a5ce2e43a1a719475616da5e92936d930c'};rendererDll=@{bytes=[int64]11887616;sha='7578cd5da8a6831900c66680c4b94f89e64b6b294623709817848b02219aeac2'};presentMonExe=@{bytes=[int64]980320;sha='b2a706bc6ad475749e3b7e3409263aa1e6906d45bdcf993f6dbc0f660188f1af'}}
function Require([bool]$ok,[string]$why){if(-not $ok){throw "r12 installer rejected: $why"}}
function Full([string]$p){return [IO.Path]::GetFullPath($p)}
function Safe-Relative([string]$p){Require (-not [string]::IsNullOrWhiteSpace($p) -and -not $p.Contains('\') -and -not $p.StartsWith('/') -and $p -notmatch '(^|/)\.\.(/|$)' -and $p -notmatch '(^|/)\./') "unsafe relative path: $p";return $p}
function Require-Regular([string]$p,[int64]$limit){$f=Get-Item -LiteralPath (Full $p) -Force;Require (-not $f.PSIsContainer -and ($f.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0 -and $f.Length -le $limit) "bounded regular file required: $p";return $f}
function Hash-Bounded([string]$p,[int64]$limit){$f=Require-Regular $p $limit;$sha=[Security.Cryptography.SHA256]::Create();$s=[IO.File]::Open($f.FullName,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$b=New-Object byte[] $Chunk;$nTotal=[int64]0;try{while(($n=$s.Read($b,0,$b.Length))-gt 0){$nTotal+=$n;Require ($nTotal -le $limit) "hash bound exceeded: $p";$sha.TransformBlock($b,0,$n,$b,0)|Out-Null};$sha.TransformFinalBlock([byte[]]::new(0),0,0)|Out-Null;return [ordered]@{bytes=$nTotal;sha256=([BitConverter]::ToString($sha.Hash)-replace '-','').ToLowerInvariant()}}finally{$s.Dispose();$sha.Dispose()}}
function Read-BoundedJson([string]$p){$f=Require-Regular $p $MaxJson;return [IO.File]::ReadAllText($f.FullName)|ConvertFrom-Json}
function Parse-PS([string]$p){$t=$null;$e=$null;[void][Management.Automation.Language.Parser]::ParseFile((Full $p),[ref]$t,[ref]$e);Require ($e.Count -eq 0) "PowerShell parse failed: $p"}
function Hash-ZipEntry([IO.Compression.ZipArchiveEntry]$entry,[int64]$limit){Require ($entry.Length -le $limit) 'ZIP metadata exceeds bound';$s=$entry.Open();$sha=[Security.Cryptography.SHA256]::Create();$b=New-Object byte[] $Chunk;$total=[int64]0;try{while(($n=$s.Read($b,0,$b.Length))-gt 0){$total+=$n;Require ($total -le $limit) 'ZIP metadata bound exceeded';$sha.TransformBlock($b,0,$n,$b,0)|Out-Null};$sha.TransformFinalBlock([byte[]]::new(0),0,0)|Out-Null;return ([BitConverter]::ToString($sha.Hash)-replace '-','').ToLowerInvariant()}finally{$s.Dispose();$sha.Dispose()}}
function Write-FreshJson([string]$p,[object]$v){$full=Full $p;Require (-not(Test-Path -LiteralPath $full)) "fresh output required: $full";$parent=Split-Path -Parent $full;if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$full.$PID.$([guid]::NewGuid().ToString('N')).tmp";[IO.File]::WriteAllText($tmp,(($v|ConvertTo-Json -Depth 18)+"`r`n"),[Text.Encoding]::UTF8);[IO.File]::Move($tmp,$full)}
function Under([string]$child,[string]$parent){$c=(Full $child).TrimEnd('\')+'\';$p=(Full $parent).TrimEnd('\')+'\';return $c.StartsWith($p,[StringComparison]::OrdinalIgnoreCase)}
function Extract-ZipEntry([IO.Compression.ZipArchiveEntry]$entry,[string]$destination,[int64]$expectedBytes,[string]$expectedSha){$rel=Safe-Relative ([string]$entry.FullName);Require ($entry.Length -eq $expectedBytes -and $entry.Length -le $MaxSource) "ZIP bytes mismatch: $rel";$dest=Full $destination;Require (Under $dest $StageRoot) "ZIP destination escapes stage: $rel";Require (-not(Test-Path -LiteralPath $dest)) "stage destination collision: $rel";$parent=Split-Path -Parent $dest;if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$input=$entry.Open();$output=[IO.File]::Open($dest,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);$sha=[Security.Cryptography.SHA256]::Create();$b=New-Object byte[] $Chunk;$total=[int64]0;$actual=$null;try{while(($n=$input.Read($b,0,$b.Length))-gt 0){$total+=$n;Require ($total -le $MaxSource) "ZIP extraction bound exceeded: $rel";$output.Write($b,0,$n);$sha.TransformBlock($b,0,$n,$b,0)|Out-Null};$sha.TransformFinalBlock([byte[]]::new(0),0,0)|Out-Null;$actual=([BitConverter]::ToString($sha.Hash)-replace '-','').ToLowerInvariant();$output.Flush($true)}finally{$output.Dispose();$input.Dispose();$sha.Dispose()};Require ($total -eq $expectedBytes -and $actual -ceq $expectedSha.ToLowerInvariant()) "ZIP hash mismatch: $rel"}
$stage=Full $StageRoot;$factory=Full $FactoryRoot;$control=Full $ControlRoot;$controlReceipts=Full $ControlReceiptRoot;$run=Full $RunRoot;$zipFull=Full $ZipPath;$metaFull=Full $MetadataPath;$controlsFull=Full $ControlsReceiptPath
foreach($fresh in @($stage,$factory,$control,$controlReceipts,$run,(Full $PlanPath),(Full $ManifestPath),(Full $RunManifestPath))){Require (-not(Test-Path -LiteralPath $fresh)) "fresh path required: $fresh"}
$meta=Read-BoundedJson $metaFull;Require ([string]$meta.schema -eq 'sr0-display-selfjob-r12-source-pack' -and [int]$meta.sourceCount -ge 29 -and [int]$meta.binaryCount -eq 3 -and [int]$meta.nativeActions -eq 0 -and [bool]$meta.qualificationClaim -eq $false) 'source pack metadata schema/count/flags';$sourceRows=@($meta.sourceRows);$binaryRows=@($meta.binaryRows);Require ($sourceRows.Count -eq [int]$meta.sourceCount -and $binaryRows.Count -eq 3 -and @($sourceRows|Where-Object{$_.name -eq 'admissionHelper'}).Count -eq 1) 'source pack source/binary/helper counts'
$zipItem=Require-Regular $zipFull $MaxZip;Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead($zipFull);$entries=@{};$zipTotal=[int64]0;try{Require ($zip.Entries.Count -eq ($sourceRows.Count+1)) 'ZIP source count/metadata bound';foreach($entry in $zip.Entries){$name=Safe-Relative ([string]$entry.FullName);Require (([int64]$entry.ExternalAttributes -shr 16 -band 0xF000) -ne 0xA000) "ZIP symlink entry rejected: $name";Require ($name -notmatch '^source/[^/]+/\.\.') "ZIP traversal path: $name";Require (-not $entries.ContainsKey($name)) "duplicate ZIP entry: $name";$zipTotal+=[int64]$entry.Length;Require ($zipTotal -le $MaxZip) 'ZIP uncompressed bound';$entries[$name]=$entry};Require ($entries.ContainsKey('source-pack-metadata.json')) 'ZIP metadata missing';Require ((Hash-ZipEntry $entries['source-pack-metadata.json'] $MaxJson) -ceq (Hash-Bounded $metaFull $MaxJson).sha256) 'ZIP metadata drift';$zipMeta=Read-BoundedJson $metaFull;Require (([string]$zipMeta.schema -eq [string]$meta.schema) -and (@($zipMeta.sourceRows).Count -eq $sourceRows.Count)) 'ZIP metadata join';$stageNew=New-Item -ItemType Directory -Path $stage -Force; $total=[int64]0;foreach($row in $sourceRows){$rel=Safe-Relative ([string]$row.path);$entryName='source/'+$rel;Require ($entries.ContainsKey($entryName)) "ZIP source missing: $rel";$h=[string]$row.sha256;Require ($h -match '^[0-9a-fA-F]{64}$') "source hash invalid: $rel";$target=Join-Path $stage $rel;Extract-ZipEntry $entries[$entryName] $target ([int64]$row.bytes) $h;$total+=[int64]$row.bytes;Require ($total -le $MaxTotal) 'source total bound';if(([IO.Path]::GetExtension($target) -ieq '.ps1')){Parse-PS $target}}
}finally{$zip.Dispose()}
$binaryMap=@{workloadExe=$WorkloadExe;rendererDll=$RendererDll;presentMonExe=$PresentMonExe};$allRows=@($sourceRows);foreach($row in $binaryRows){$name=[string]$row.name;Require ($binaryMap.ContainsKey($name) -and $Expected.ContainsKey($name)) "unexpected binary role: $name";Require ([int64]$row.bytes -eq [int64]$Expected[$name].bytes -and ([string]$row.sha256).ToLowerInvariant() -ceq [string]$Expected[$name].sha) "original binary metadata drift: $name";$actual=Hash-Bounded $binaryMap[$name] $MaxSource;Require ($actual.bytes -eq [int64]$row.bytes -and $actual.sha256 -ceq ([string]$row.sha256).ToLowerInvariant()) "binary pin mismatch: $name";$allRows+=[ordered]@{name=$name;path=[string]$row.path;source=[string]$row.source;bytes=[int64]$row.bytes;sha256=([string]$row.sha256).ToLowerInvariant();external=$true};$total+=$actual.bytes}
Require ($allRows.Count -eq ($sourceRows.Count+$binaryRows.Count) -and $total -le $MaxTotal) 'source closure/aggregate bound'
$sourceInput=[ordered]@{schema='sr0-display-selfjob-r12-source-input-rows';rows=$allRows;totalBytes=$total};Write-FreshJson (Join-Path $stage 'source-input-rows.json') $sourceInput
$byName=@{};foreach($row in $sourceRows){$byName[[string]$row.name]=$row};$paths=@{};foreach($name in $byName.Keys){$paths[$name]=Join-Path $stage ([string]$byName[$name].path)};$pins=[ordered]@{};foreach($row in $sourceRows){$pins[[string]$row.name]=[string]$row.sha256};$pins.drainControlTestSha256=$pins.controlsDrain;$pins.drainControlRunnerSha256=$pins.drainControls;$pins.collector=$pins.collector;$pins.identityHelper=$pins.identityHelper;$pins.drainHelper=$pins.drainHelper
New-Item -ItemType Directory -Path $control,$controlReceipts,$run -Force|Out-Null;Copy-Item -LiteralPath $controlsFull -Destination (Join-Path $controlReceipts 'source-controls-donor-r10.json') -Force;Require ((Hash-Bounded $controlsFull $MaxJson).sha256 -ceq (Hash-Bounded (Join-Path $controlReceipts 'source-controls-donor-r10.json') $MaxJson).sha256) 'donor controls copy drift'
$plan=[ordered]@{schema='sr0-display-selfjob-v4-fresh-one-run-r12';status='source-pin-plan';execution='fresh native diagnostic only; strict display gate retained; no eligibility claim';stageRoot=$stage;base=(Full $Base);factoryRoot=$factory;controlRoot=$control;controlReceiptRoot=$controlReceipts;requiredControlReceipts=@('drain-controls-r11.json');donorControlReceipt='source-controls-donor-r10.json';runRoot=$run;admissionManifestPath=(Full $ManifestPath);manifestPath=(Full $RunManifestPath);sourceRowsPath=(Join-Path $stage 'source-input-rows.json');taskName='SR0-factory-display-selfjob-v7-root-r13';tag='SR0-factory-display-selfjob-v7-root-r13';schedulePath=$paths.schedule;workerPath=$paths.worker;collectorPath=$paths.collector;coordinatorPath=$paths.coordinator;wrapperPath=$paths.wrapper;frozenTaskPath=$paths.frozenTask;drainTaskPath=$paths.drainTask;helperPath=$paths.helper;drainHelperPath=$paths.drainHelper;identityHelperPath=$paths.identityHelper;parserPath=$paths.parser;launcherHelperPath=$paths.launcherHelper;admissionHelperPath=$paths.admissionHelper;workloadExe=(Full $WorkloadExe);rendererDll=(Full $RendererDll);presentMonExe=(Full $PresentMonExe);workloadExeSha256=$Expected.workloadExe.sha;rendererDllSha256=$Expected.rendererDll.sha;presentMonSha256=$Expected.presentMonExe.sha;admissionHelperSha256=$pins.admissionHelper;lockPath=(Full $LockPath);memoryLimitFlags='0x200';aggregateJobMemoryLimitBytes=$Memory;killOnJobClose=$false;deadlineSeconds=900;pollSeconds=1;warmup=10;measure=60;runs=1;rows=200;keyRate=10;noActivate=$true;noResources=$true;streamCapBytes=8388608;csvCapBytes=67108864;nativeActions=0;qualificationClaim=$false;sourcePins=$pins;sourceFiles=$allRows};Write-FreshJson $PlanPath $plan
$manifest=[ordered]@{schema='sr0-display-selfjob-v5-one-shot-admission-r12';candidateLineage='native-r10c-recovery-v1-r12';taskName=$plan.taskName;tag=$plan.tag;base=$plan.base;controlRoot=$control;controlReceiptRoot=$controlReceipts;requiredControlReceipts=@('drain-controls-r11.json');donorControlReceipt='source-controls-donor-r10.json';noActivate=$true;noResources=$true;runs=1;warmup=10;measure=60;rows=200;keyRate=10;deadlineSeconds=900;pollSeconds=1;aggregateJobMemoryLimitBytes=$Memory;aggregateLimitFlags=512;killOnJobClose=$false;workloadExe=$plan.workloadExe;rendererDll=$plan.rendererDll;presentMonExe=$plan.presentMonExe;lockPath=$plan.lockPath;runRoot=$run;resultFile=(Join-Path $run 'result-workload.txt');memoryReceiptPath=(Join-Path $run 'collector-receipt.json');startReceiptPath=(Join-Path $run 'start-receipt.json');coordinatorOutputPath=(Join-Path $run 'coordinator-verdict.json');launcherReceiptPath=(Join-Path $run 'launcher-receipt.json');sourceRowsPath=$plan.sourceRowsPath;controlsReceiptSha256=(Hash-Bounded $controlsFull $MaxJson).sha256};foreach($row in $sourceRows){$manifest[([string]$row.name)+'Path']=Join-Path $stage ([string]$row.path);$manifest[([string]$row.name)+'Sha256']=[string]$row.sha256};$manifest.workloadExeSha256=$plan.workloadExeSha256;$manifest.rendererDllSha256=$plan.rendererDllSha256;$manifest.presentMonSha256=$plan.presentMonSha256;Write-FreshJson $ManifestPath $manifest
if($RunControls){$runner=$paths.drainControls;& $runner -StageRoot $stage -PlanPath (Full $PlanPath) -OutputPath (Join-Path $controlReceipts 'drain-controls-r11.json');Require ($? -eq $true) 'r12 source controls failed';& (Join-Path $PSScriptRoot 'preflight-r12.ps1') -StageRoot $stage -PlanPath (Full $PlanPath) -AdmissionManifestPath (Full $ManifestPath) -RunManifestPath (Full $RunManifestPath) -ControlsReceiptPath (Join-Path $controlReceipts 'drain-controls-r11.json') -ReceiptPath (Join-Path $stage 'source-preflight-r12.json');Require ($? -eq $true) 'r12 source preflight failed'}
$out=[ordered]@{kind='sr0-display-selfjob-r12-source-install';status=if($RunControls){'passed-source-install-controls'}else{'staged-source-only'};stageRoot=$stage;planPath=(Full $PlanPath);admissionManifestPath=(Full $ManifestPath);runManifestPath=(Full $RunManifestPath);sourceCount=$allRows.Count;sourceBytes=$total;nativeActions=0;lockActions=0;nativeQualificationClaim=$false;runControls=[bool]$RunControls;checkedAt=[DateTimeOffset]::UtcNow.ToString('o')};$out|ConvertTo-Json -Depth 8;exit 0
